success = True success = test_sierpinski_centroids() and success success = test_ffe_quantization() and success
if success: print("\n" + "=" * 50) print("✓ All compatibility tests passed") print("\nNote: This verifies core algorithms work independently.") print("Full pipeline requires deepseek_adapter dependency.") else: print("\n" + "=" * 50) print("✗ Some tests failed") sys.exit(1)
